return "\n.package {\n    type 0 : integer\n    session 1 : integer\n}\n\nheartbeat 1 {\n    response {\n        msg 0 : integer #\n        power 1 : string\n        platform 2 : string\n    }\n}\n.consumeids {  #消耗信息\n    entityid 0 : integer\n    num      1 : integer\n}\n\n#聊天返回\nchatting 2 {\n    request {\n        name 0 : string\n        msg 1 : string\n        time 2 : string \n    }\n}\n\n#客户端通知\nalert_client 3 {\n    request {\n        system 0 : *integer\n        systeminfo 1 : *string\n    }\n}\n\noffline_alert 4 {\n    request {\n        msg 0 : string\n    }\n}\n\nlogout_order 5 {\n    request {\n        order 0 : integer\n    }\n}\n\n.sub_attr {\n    key 0 : string\n    value 1 : *integer\n}\n\n.item_component {\n    attr 0 : integer\n    effect 1 : integer\n    extra 2 : integer\n    lock 3 : boolean\n    use 4 : integer\n}\n\n.item_eatable {\n    color 0 : integer \n    smell 1 : integer\n    taste 2 : integer\n    sour 3 : integer\n    sweet 4 : integer\n    hot 5 : integer\n    salty 6 : integer\n    debuff_activity 7 : integer\n    debuff_favor 8 : integer\n    raw_foods 9 : *integer\n    coke_foods 10 : *integer\n}\n\n.item_horcrux {\n    star        0 : integer\n    lock        1 : boolean\n    fighting    2 : boolean\n    hlv         3 : integer\n    exp         4 : integer\n    hclass      5 : integer\n    hbreak      6 : integer\n    dfac        7 : integer\n    hfac        8 : integer\n}\n\n.item_weapon {\n    exp 0 : integer\n    level 1 : integer\n    skills 2 : integer\n    maxStars 3 : integer\n    nowStars 4 : integer\n    use 5 : integer\n    lock 6 : boolean\n}\n\n.item {     #物品\n    entityid 0 : integer                #物品entityid\n    itemid 1 : integer                  #物品id\n    itemtype 2 : integer                #物品类型\n    itemcount 3 : integer               #物品数量\n    component_attr 4 : item_component\n    eatable_attr 5 : item_eatable\n    horcrux_attr 6 : item_horcrux\n    weapon_attr 7 : item_weapon\n}\n\n.soul_favor_san {\n    soulid 0 : integer\n    sanvalue 1 : integer\n    favor_lv 2 : integer\n    favor_degree 3 : integer\n}\n\n.plotinfo {\n    plotState 0 : integer\n    plotClassId 1 : integer\n    step 2 : integer\n    order 3 : integer\n}\n\nsync_player_item 6 {\n    request {\n        items 0 : *item\n    }\n}\n\nsync_player_hangup 7 {\n    request {\n        gold 0 : string\n        exp 1 : string\n        grade 2 : integer\n        strengthpoint 3 : integer\n        items 4 : *item\n        dropcachetime 5 : integer\n        totalexp 6 : string\n    }\n}\n\n# 活动系统\n.activitylist {\n    id 0 : integer\n    status 1 : integer\n\n    .module_stat {\n        activitymodule 0 : string\n        finished 1 : boolean\n    }\n    module_stat 2 : *module_stat\n\n    .activitymodule {\n        module 0 : string\n        status 1 : integer\n        starttime 2 : string\n        finishtime 3 : string\n    }\n\n    modules 3 : *activitymodule\n}\n\nsubscribe_activity_msg 8 {\n    request {\n        id 0 : integer\n        msg 1 : string\n        activityinfo 2 : activitylist\n    }\n}\n\ndaily_update 9 {}\n\nnew_complete_tasks 10 {\n    request {\n        tasks 0 : *integer\n    }\n}\n\nactivity_alert 11 {\n    request {\n        alerttype 0 : string\n        activities 1 : *integer\n    }\n}\n\nsync_dropcache_time 12 {\n    request {\n        dropcachetime 0 : integer\n    }\n}\n\ntiming_trigger_plot 13 {\n    request {\n        plotinfos 0 : *plotinfo\n    }\n}\n\npurchase_success 14 {\n    request {\n        product         0 : integer\n        diamond         1 : integer\n        extradiamond    2 : integer\n        remain          3 : integer\n        items           4 : *item\n        gold            5 : integer\n        sp              6 : integer\n    }\n}\n\ncheck_version 15 {\n    request {\n        version 0 : string\n    }\n}\n\nrob_end 16 {}\n\nrob_start_alert 17 {\n    request {\n        msg 0 : string\n    }\n}\n\nfirework_broadcast 18 {\n    request {\n        chapter 0 : string\n        playerid 1 : string\n        itemid 2 : string\n        count 3 : string\n        name 4 : string\n        head_sculpture 5 : string\n    }\n}\n\nsalute_award_broadcast 19 {\n    request {\n        items 0 : *item\n    }\n}\n\nsync_nianshou_item 20 {\n    request {\n        items 0 : *item\n    }\n}\n\nweekly_update 21 {}\n\nsync_activity_twsit_unlock 22 {\n    request {\n        twisttype 0 : integer\n    }\n}\nmonthly_update 23 {}\n\nfriend_new_application 100 {}\nfriend_new_gift 101 {\n    request {\n        playerid 0 : integer\n        gift 1 : integer\n    }\n}\n#进入社团通知\nfamily_enter_notice 110 {\n    request {\n        familyid 0 : integer\n    }\n}\n#职位变动通知\nfamily_title_change_notice 111 {\n    request {\n        familyid 0 : integer\n        title 1 : integer\n    }\n}\n#踢出社团通知\nfamily_kick_notice 112 {\n    request {\n        familyid 0 : integer\n    }\n}\n\nnotice_add_item 120 {\n    request {\n        items 0 : *item\n        diamond 1 : integer\n        gold 2 : integer\n        client_not_pop 3 : boolean      # 客户端不弹出弹窗 true--不弹出\n    }\n}\n#社团消息通知\nfamily_chat_notice 113 {\n    request {\n        .chat {\n            msgid 0 : integer\n            playerid 1 : integer\n            nickname 2 : string #昵称\n            head_sculpture 3 : integer #玩家头像\n            msg 4 : string #聊天内容\n            time 5 : integer #时间\n            class 6 : integer # 班级\n            level 7 : integer # 等级\n        }\n        list 0 : *chat\n    }\n}\n\n#聊天通知\n#消息过多的时候会合并多个发送到客户端\nchat_message_notice 200 {\n    request {\n        .chatinfo {\n            channel 0 : integer #聊天频道\n            roomid 1 : integer #房间id\n            playerid 2 : integer #消息发送者id\n            head_sculpture 3 : integer #头像\n            name 4 : string #昵称\n            message 5 : string #聊天内容\n            time 6 : integer #消息发送时间\n        }\n        list 0 : *chatinfo\n    }\n}\nnotice_delete_item 121 {\n    request {\n        consumes 0 : *consumeids\n        diamond 1 : integer\n        gold 2 : integer\n    }\n}\n\n#通知私聊新消息\nchat_new_private_message 201 {\n    request {\n        playerid 0 : integer #发送者id\n    }\n}\n\n#服务端错误返回\nservice_error 301 {\n    request {\n        request_errmsg 0 : string\n        request_traceback 1 : string\n    }\n}\n\n#社团心愿板通知\nfamily_wish_notice 114 {\n    request {\n        tp 0 : integer #1可领取，2可收礼\n    }\n}\n\n#订阅状态更新\nsubscribe_status_change 202 {\n    request {\n        id 0 : integer\n        remain 1 : integer\n        subscribe_status 2 : integer\n        subscribe_deduct_fail 3 : string\n    }\n}\n\n#同步背包上限\nsync_bagweight 203 {\n    request {\n        cachelimit 0 : integer\n        bagweight 1 : *string\n    }\n}\n\n#同步学员信息\nsync_servant_horcrux 204 {\n    request {\n        .servant_horcrux {  #魂姬吞噬的魂器\n            skillid 0 : integer #技能id 未生效负值\n            hp 1 : integer\n            damage 2 : integer\n            disable 3 : boolean #魂器槽不生效\n            newskill 4 : integer #待替换的技能\n            newhp 5 : integer #待替换血量\n            newdamage 6 : integer #待替换伤害\n            horcrux 7 : integer #魂器id\n            newhorcrux 8 : integer #待替换魂器id\n            itemid 9 : integer #魂器物品id\n            skillid2 10 : integer #技能id 未生效负值\n            newskill2 11 : integer #待替换的技能2\n        }\n        id          0 : integer\n        horcruxs    1: *servant_horcrux #魂姬吞噬的魂器\n    }\n}\n\n"
